import { DateTime, Option, Schema, SchemaGetter } from "effect";
export const PositiveInt = Schema.Int.check(Schema.isGreaterThan(0));
export const NonNegativeInt = Schema.Int.check(Schema.isGreaterThanOrEqualTo(0));
export const RelativePath = Schema.String.pipe(Schema.brand("RelativePath"), Schema.annotate({ identifier: "RelativePath" }));
export const AbsolutePath = Schema.String.pipe(Schema.brand("AbsolutePath"), Schema.annotate({ identifier: "AbsolutePath" }));
export const optional = (schema) => Schema.optionalKey(schema).pipe(Schema.decodeTo(Schema.optional(Schema.toType(schema)), {
    decode: SchemaGetter.passthrough({ strict: false }),
    encode: SchemaGetter.transformOptional(Option.filter((value) => value !== undefined)),
}));
// Effect schemas expose `make` through prototype getters, so `Object.assign` cannot override it.
// Defining the properties replaces a constructor as long as the schema's own `make` has not been read.
export const withStatics = (schema, methods) => Object.defineProperties(schema, Object.getOwnPropertyDescriptors(methods));
export const statics = (methods) => (schema) => withStatics(schema, methods(schema));
export const DateTimeUtcFromMillis = Schema.Finite.pipe(Schema.decodeTo(Schema.DateTimeUtc, {
    decode: SchemaGetter.transform((value) => DateTime.makeUnsafe(value)),
    encode: SchemaGetter.transform((value) => DateTime.toEpochMillis(value)),
}));
